//==========================================================================
// QULLAMAGGIE-STYLE DAILY BREAKOUT  (long only, swing trading)
// For AmiBroker 5.x/6.x - daily bars, portfolio backtester
//
// Rules implemented (from Kristjan Kullamagi's published setup + public
// systematic re-builds):
//   1. Leaders: big prior move (any of 1M / 3M / 6M gain thresholds)
//   2. Volatility: ADR% (20d) above a minimum; liquidity filter
//   3. Base: tight, orderly consolidation near a rising 10/20 EMA,
//      higher lows, not extended
//   4. Entry: break above the base high (buy-stop at pivot, gap -> Open)
//   5. Stop: no wider than 1 ADR below entry (optionally tighter: base low)
//   6. Exit: sell part after ~3-5 bars, stop to break-even on the rest,
//      trail the remainder - first daily CLOSE below the 10 (or 20) MA
//   7. Market filter: index 10 EMA > 20 EMA (his regime rule) - optional
//   8. Sizing: fixed % of equity risked per trade (risk / stop distance)
//
// NOT testable on daily data: his opening-range-high entries (1/5/60 min)
// and "low of day" stop. Here the stop is placed ADR-based at entry so
// nothing uses information from later in the bar.
//
// ALL SIGNALS ARE DECIDED ON THE PRIOR CLOSE; the only intrabar assumption
// is that a pivot break fills at max(Open, pivot) and stops fill at
// min(Open, stop).
//==========================================================================
_SECTION_BEGIN("Qullamaggie Breakout");

//------------------------------ PARAMETERS ------------------------------
// --- Leaders / universe (any ONE of the three momentum legs qualifies)
Mom1M       = Param("1M gain % (21 bars)",          25,   0, 500,  1);
Mom3M       = Param("3M gain % (63 bars)",          50,   0, 1000, 1);
Mom6M       = Param("6M gain % (126 bars)",        150,   0, 2000, 5);
ADRmin      = Param("Min ADR% (20d)",                4,   1, 20,   0.5);
MinTurnover = Param("Min 20d avg turnover (Close*Vol, your currency)", 10000000, 0, 10000000000, 1000000);
MinPrice    = Param("Min price",                    20,   0, 100000, 1);

// --- Base / consolidation
BaseLen     = Param("Base length (bars)",           10,   5, 60,   1);   // ~2 weeks .. 2 months = 10..40
BaseMaxADR  = Param("Max base range (x ADR)",        3,   0.5, 15, 0.25);
NearMA      = Param("Max distance above EMA20 (x ADR)", 2, 0.5, 10, 0.25);
ReqHL       = ParamToggle("Require higher lows in base", "Off|On", 1);

// --- Market regime
IdxSym      = ParamStr("Index symbol for regime filter", "^NIFTY50");
MktMode     = Param("Market filter: 0 off, 1 idx EMA10>EMA20, 2 idx>EMA140, 3 EMA10>EMA20 & both rising, 4 EMA10>EMA20 & idx>EMA140", 1, 0, 4, 1);
MaxGapPct   = Param("Reject symbol if any gap > % in last 130 bars (bad splits; 200 = off)", 40, 10, 200, 5);

// --- Stop / exits
StopADRMult = Param("Stop width (x ADR, max 1 per rules)", 1, 0.25, 2, 0.05);
StopMode    = Param("Stop mode: 1 ADR-based, 2 tighter of ADR & base low", 1, 1, 2, 1);
StopLowBars = Param("Base-low stop lookback (mode 2)", 5, 2, 20, 1);
MinStopPct  = Param("Min stop distance %",           1.5, 0.5, 10, 0.1);
EntryDayStop= Param("Entry-day stop: 0 off (optimistic), 1 Low<=stop (pessimistic), 2 gap entries use Low / intraday entries use Close", 2, 0, 2, 1);
PartialPct  = Param("Partial exit % of position (0 = off)", 33, 0, 50, 1);
PartialDays = Param("Partial exit at bar N after entry", 4, 2, 8, 1);
PartialIfProfit = ParamToggle("Partial only if in profit", "Off|On", 1);
TrailLen    = Param("Trail MA length",              10,   5, 50,   1);
TrailEMA    = ParamToggle("Trail MA type", "SMA|EMA", 1);
TrailStart  = Param("First bar (after entry) to check trail", 1, 1, 10, 1);

// --- Risk / portfolio
RiskPct     = Param("Risk per trade % of equity",    0.75, 0.1, 3, 0.05);
MaxPosPct   = Param("Max position size % of equity", 20,  5, 100, 1);
MaxPos      = Param("Max open positions",            10,  1, 50,  1);
SlipPct     = Param("Slippage % per side",           0.10, 0, 2, 0.05);
CommPct     = Param("Commission+taxes % per side",   0.21, 0, 1, 0.01);
InitEq      = Param("Initial equity",           100000, 10000, 1000000000, 10000);

//--------------------------- BACKTEST SETTINGS ---------------------------
SetTradeDelays( 0, 0, 0, 0 );            // we model fills manually via Buy/SellPrice
SetOption( "InitialEquity", InitEq );
SetOption( "MaxOpenPositions", MaxPos );
SetOption( "AllowSameBarExit", True );
SetOption( "CommissionMode", 1 );        // percent of trade value
SetOption( "CommissionAmount", CommPct );
RoundLotSize = 1;

//------------------------------ INDICATORS -------------------------------
E10 = EMA( C, 10 );
E20 = EMA( C, 20 );
TrailMA = IIf( TrailEMA, EMA( C, TrailLen ), MA( C, TrailLen ) );

// ADR% = 100 * ( SMA( High/Low, 20 ) - 1 )  (gaps excluded by design)
ADRNow = 100 * ( MA( IIf( Low > 0, High / Low, 1 ), 20 ) - 1 );

// Momentum leaders
Surge = ROC( C, 21 ) >= Mom1M OR ROC( C, 63 ) >= Mom3M OR ROC( C, 126 ) >= Mom6M;

// Liquidity / price
Liq = MA( C * V, 20 ) >= MinTurnover AND C >= MinPrice;

// Trend: price above rising 10/20 EMA
Trend = C > E10 AND C > E20 AND E10 > E20 AND E20 > Ref( E20, -5 );

// Not extended above the 20 EMA
Ext = ( C - E20 ) / E20 * 100 <= NearMA * ADRNow;

// Base (consolidation) - evaluated on the last BaseLen bars
BaseHi    = HHV( H, BaseLen );
BaseLo    = LLV( L, BaseLen );
BaseRange = ( BaseHi - BaseLo ) / BaseLo * 100;
Tight     = BaseRange <= BaseMaxADR * ADRNow;

HalfLen = Int( BaseLen / 2 );
HL      = LLV( L, HalfLen ) >= Ref( LLV( L, HalfLen ), -HalfLen );
HLok    = HL OR ( ReqHL == 0 );

// Market regime (index)
idxC = Foreign( IdxSym, "C", True );
iE10 = EMA( idxC, 10 );
iE20 = EMA( idxC, 20 );
iE140 = EMA( idxC, 140 );
MktOKNow = 1;
if( MktMode == 1 ) MktOKNow = iE10 > iE20;
if( MktMode == 2 ) MktOKNow = idxC > iE140;
if( MktMode == 3 ) MktOKNow = iE10 > iE20 AND iE10 > Ref( iE10, -1 ) AND iE20 > Ref( iE20, -1 );
if( MktMode == 4 ) MktOKNow = iE10 > iE20 AND idxC > iE140;
MktOKNow = Nz( MktOKNow );

// Setup as of a bar's close (usable for tomorrow's entry)
// Data sanity: unadjusted splits show up as huge gaps (e.g. a -88% "trade" in the first report)
GapPct  = Nz( abs( O / Ref( C, -1 ) - 1 ) * 100 );
BadData = HHV( GapPct, 130 ) > MaxGapPct;

SetupNow = Surge AND Liq AND Trend AND Ext AND Tight AND HLok AND ( ADRNow >= ADRmin ) AND MktOKNow AND !BadData;

//--------------- SHIFT TO "PRIOR BAR" -> no look-ahead -------------------
Setup  = Nz( Ref( SetupNow, -1 ) );
Pivot  = Nz( Ref( BaseHi, -1 ) );             // highest high of the base, ending yesterday
ADRp   = Nz( Ref( ADRNow, -1 ) );
LowRef = Nz( Ref( LLV( L, StopLowBars ), -1 ) );

Trig = Setup AND High > Pivot AND Pivot > 0;  // buy-stop at pivot triggered today

//------------------- TRADE STATE MACHINE (per symbol) --------------------
Buy = Close * 0;
Sell = Close * 0;
Short = Close * 0;
Cover = Close * 0;
BuyPrice = Close;
SellPrice = Close;
PosPct = Close * 0;

inTrade = False;
exitNext = False;
partialDone = False;
entryPx = 0;
stopPx = 0;
initStop = 0;
iEntry = 0;
Warm = 130;

for( i = Warm; i < BarCount; i++ )
{
    if( inTrade )
    {
        if( exitNext )
        {
            // closed below trail MA yesterday -> sell at today's open
            Sell[ i ] = 1;
            SellPrice[ i ] = Max( Low[ i ], Open[ i ] * ( 1 - SlipPct / 100 ) );
            inTrade = False;
            exitNext = False;
        }
        else if( Low[ i ] <= stopPx )
        {
            // stop (initial or break-even); gaps fill at the open
            xp = Min( Open[ i ], stopPx );
            Sell[ i ] = 1;
            SellPrice[ i ] = Max( Low[ i ], xp * ( 1 - SlipPct / 100 ) );
            inTrade = False;
        }
        else
        {
            nb = i - iEntry;

            // partial profit at the close of bar N, then stop -> break-even
            if( !partialDone AND PartialPct > 0 AND nb == PartialDays
                AND ( Close[ i ] > entryPx OR PartialIfProfit == 0 ) )
            {
                Buy[ i ] = sigScaleOut;
                BuyPrice[ i ] = Close[ i ];
                SellPrice[ i ] = Close[ i ];
                partialDone = True;
                stopPx = Max( stopPx, entryPx );
            }

            // trail: first close below MA, only once MA is above the initial stop
            if( nb >= TrailStart AND TrailMA[ i ] > initStop AND Close[ i ] < TrailMA[ i ] )
                exitNext = True;
        }
    }
    else if( Trig[ i ] )
    {
        ep = Max( Open[ i ], Pivot[ i ] );
        ep = Min( High[ i ], ep * ( 1 + SlipPct / 100 ) );

        sp = ep * ( 1 - StopADRMult * ADRp[ i ] / 100 );
        if( StopMode == 2 ) sp = Max( sp, LowRef[ i ] );
        sp = Min( sp, ep * ( 1 - MinStopPct / 100 ) );

        StopDistPct = ( ep - sp ) / ep * 100;

        Buy[ i ] = 1;
        BuyPrice[ i ] = ep;
        PosPct[ i ] = Min( MaxPosPct, RiskPct / StopDistPct * 100 );

        // Entry-day stop. Gap entries (Open >= pivot): whole-day low happens after the fill.
        // Intraday entries (Open < pivot): the low may have come BEFORE the break, so mode 2 only
        // counts the stop if the day CLOSED at/below it.
        hitStop = False;
        if( EntryDayStop == 1 ) hitStop = Low[ i ] <= sp;
        if( EntryDayStop == 2 )
        {
            if( Open[ i ] >= Pivot[ i ] ) hitStop = Low[ i ] <= sp;
            else hitStop = Close[ i ] <= sp;
        }

        if( hitStop )
        {
            // stopped out the same day
            Sell[ i ] = 1;
            SellPrice[ i ] = Max( Low[ i ], sp * ( 1 - SlipPct / 100 ) );
        }
        else
        {
            inTrade = True;
            exitNext = False;
            partialDone = False;
            entryPx = ep;
            stopPx = sp;
            initStop = sp;
            iEntry = i;
        }
    }
}

//---------------------------- POSITION SIZING ----------------------------
PositionSize = -PosPct;                                   // % of portfolio equity
SetPositionSize( PartialPct, spsPercentOfPosition * ( Buy == sigScaleOut ) ); // scale-out size
PositionScore = 1000 + Nz( Ref( ROC( C, 21 ) + ROC( C, 63 ) + ROC( C, 126 ), -1 ) ); // strongest leaders first

//------------------------------ EXPLORATION ------------------------------
// Run Explore on the last bar = tomorrow's watchlist (buy-stop levels)
if( Status( "action" ) == actionExplore )
{
    Filter = SetupNow AND Status( "lastbarinrange" );
    AddColumn( C,                                   "Close",           1.2 );
    AddColumn( BaseHi,                              "Buy above",       1.2 );
    AddColumn( BaseHi * ( 1 - StopADRMult * ADRNow / 100 ), "Stop @pivot", 1.2 );
    AddColumn( ADRNow,                              "ADR%",            1.1 );
    AddColumn( BaseRange,                           "Base range%",     1.1 );
    AddColumn( ROC( C, 21 ),                        "1M%",             1.1 );
    AddColumn( ROC( C, 63 ),                        "3M%",             1.1 );
    AddColumn( ROC( C, 126 ),                       "6M%",             1.1 );
    AddColumn( MA( C * V, 20 ),                     "Turnover",        1.0 );
    AddColumn( MktOKNow,                            "MktOK",           1.0 );
}

//-------------------------------- CHART ----------------------------------
if( Status( "action" ) == actionIndicator )
{
    Plot( C, "Close", colorDefault, styleCandle );
    Plot( E10, "EMA10", colorOrange, styleLine );
    Plot( E20, "EMA20", colorAqua, styleLine );
    Plot( IIf( SetupNow, BaseHi, Null ), "Pivot (next bar)", colorYellow, styleDots | styleNoLine );
    PlotShapes( IIf( Buy == 1, shapeUpArrow, shapeNone ), colorBrightGreen, 0, Low, -15 );
    PlotShapes( IIf( Buy == sigScaleOut, shapeDownArrow, shapeNone ), colorBlue, 0, High, -15 );
    PlotShapes( IIf( Sell, shapeDownArrow, shapeNone ), colorRed, 0, High, -15 );
    Title = Name() + "  ADR%: " + WriteVal( ADRNow, 1.1 ) + "  Setup: " + WriteVal( SetupNow, 1.0 )
          + "  MktOK: " + WriteVal( MktOKNow, 1.0 );
}

_SECTION_END();
